#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Reemplaza los iconos de la luna con un recorte corregido (sin rastros de la
letra "n" que se colaban en el recorte anterior).
Uso: cd ~/inventario && python3 fix_recorte_final.py
"""
import os, re, base64

STATIC = os.path.expanduser('~/inventario/static')

ICON_NAV_B64 = ''
TOUCH_180_B64 = ''
TOUCH_1024_B64 = ''

# ================================================================
# 1. Guardar los iconos corregidos con nombre nuevo (v3 / v2-fix)
# ================================================================
print("1. Guardando iconos con el recorte corregido...")
archivos_nuevos = {
    'icon-nav-v2.png': ICON_NAV_B64,
    'touch-icon-v3-180.png': TOUCH_180_B64,
    'touch-icon-v3-1024.png': TOUCH_1024_B64,
}
for nombre, b64 in archivos_nuevos.items():
    ruta = os.path.join(STATIC, nombre)
    with open(ruta, 'wb') as f:
        f.write(base64.b64decode(b64))
    print("   OK " + nombre + " (" + str(os.path.getsize(ruta)) + " bytes)")

# ================================================================
# 2. Borrar los iconos anteriores (con el recorte defectuoso)
# ================================================================
print("2. Eliminando iconos anteriores (con el rastro de la 'n')...")
viejos = ['icon-nav.png', 'touch-icon-v2-180.png', 'touch-icon-v2-1024.png', 'icon-square.png']
for nombre in viejos:
    ruta = os.path.join(STATIC, nombre)
    if os.path.exists(ruta):
        os.remove(ruta)
        print("   OK " + nombre + " eliminado")

# ================================================================
# 3. Actualizar las referencias en todas las paginas HTML
# ================================================================
print("3. Actualizando referencias en el HTML...")
archivos_html = [f for f in os.listdir(STATIC) if f.endswith('.html')]
total = 0

reemplazos = [
    ('/static/icon-nav.png', '/static/icon-nav-v2.png'),
    ('/static/touch-icon-v2-180.png', '/static/touch-icon-v3-180.png'),
    ('/static/touch-icon-v2-1024.png', '/static/touch-icon-v3-1024.png'),
]

for archivo in archivos_html:
    ruta = os.path.join(STATIC, archivo)
    src = open(ruta, encoding='utf-8').read()
    original = src
    for viejo, nuevo in reemplazos:
        src = src.replace(viejo, nuevo)
    if src != original:
        open(ruta, 'w', encoding='utf-8').write(src)
        total += 1
        print("   OK " + archivo)

print("   Total: " + str(total) + " paginas actualizadas")

print()
print("=" * 50)
print("Reiniciando el servicio...")
os.system("sudo systemctl restart inventario")
print()
print("Listo. Refresca las paginas internas (Ctrl+Shift+R / Cmd+Shift+R).")
print("Para el icono de pantalla de inicio (si ya lo habias agregado):")
print("  1. Elimina el acceso directo de la pantalla de inicio")
print("  2. Ajustes -> Safari -> Borrar historial y datos de sitios web")
print("  3. Vuelve a agregarlo (Compartir -> Agregar a pantalla de inicio)")
